INSERT INTO `dictionary` (`id`, `word`, `definition`) VALUES
(2405, 'airgun', 'A kind of gun in which the elastic force of condensed air is used to discharge the ball  The air is powerfully compressed into a reservoir attached to the gun by a condensing pump and is controlled by a valve actuated by the trigger  The common BB gun is a type of air gun'),
(2406, 'Air hammer', 'a hammer powered by compressed air so as to be able to provide powerful repeated strokes a pneumatic hammer'),
