INSERT INTO `dictionary` (`id`, `word`, `definition`) VALUES
(4539, 'Anopheles', 'A genus of mosquitoes which are secondary hosts of the malaria parasites and whose bite is the usual if not the only means of infecting human beings with malaria Several species are found in the United States They may be distinguished from the ordinary mosquitoes of the genus Culex by the long slender palpi nearly equaling the beak in length while those of the female Culex are very short They also assume different positions when resting Culex usually holding the body parallel to the surface on which it rests and keeping the head and beak bent at an angle while Anopheles holds the body at an angle with the surface and the head and beak in line with it Unless they become themselves infected by previously biting a subject affected with malaria the insects cannot transmit the disease'),
(4540, 'Anophyte', 'A moss or mosslike plant which cellular stems having usually an upward growth and distinct leaves'),
(4541, 'Anopla', 'One of the two orders of Nemerteans See Nemertina'),
(4542, 'Anoplothere', 'A genus of extinct quadrupeds of the order Ungulata whose were first found in the gypsum quarries near Paris characterized by the shortness and feebleness of their canine teeth whence the name'),
