(16196, 'Cess', 'A rate or tax'),
(16197, 'Cessant', 'Inactive dormant');
INSERT INTO `dictionary` (`id`, `word`, `definition`) VALUES
(16198, 'Cessation', 'A ceasing or discontinuance as of action whether temporary or final a stop as a cessation of the war'),
(16199, 'Cessavit', 'A writ given by statute to recover lands when the tenant has for two years failed to perform the conditions of his tenure'),
(16200, 'Cesser', 'a neglect of a tenant to perform services or make payment for two years'),
(16201, 'Cessible', 'Giving way yielding'),
(16202, 'Cession', 'A yielding to physical force'),
