INSERT INTO `dictionary` (`id`, `word`, `definition`) VALUES
(22082, 'Countermand', 'To revoke a former command to cancel or rescind by giving an order contrary to one previously given as to countermand an order for goods'),
(22083, 'Countermandable', 'Capable of being countermanded revocable'),
(22084, 'Countermarch', 'To march back or to march in reversed order'),
(22085, 'Countermark', 'A mark or token added to those already existing in order to afford security or proof as an additional or special mark put upon a package of goods belonging to several persons that it may not be opened except in the presence of all a mark added to that of an artificer of gold or silver work by the Goldsmiths Company of London to attest the standard quality of the gold or silver a mark added to an ancient coin or medal to show either its change of value or that it was taken from an enemy'),
(22086, 'Countermine', 'An underground gallery excavated to intercept and destroy the mining of an enemy'),
(22087, 'Countermove', 'To move in a contrary direction to'),
