(22094, 'Counterplead', 'To plead the contrary of to plead against to deny'),
(22095, 'Counterplot', 'To oppose as another plot by plotting to attempt to frustrate as a stratagem by stratagem'),
(22096, 'Counterpoint', 'An opposite point'),
(22097, 'Counterpoise', 'To act against with equal weight to equal in weight to balance the weight of to counterbalance'),
(22098, 'Counterpole', 'The exact opposite'),
(22099, 'Counterponderate', 'To equal in weight to counterpoise to equiponderate'),
(22100, 'Counterprove', 'To take a counter proof of or a copy in reverse by taking an impression directly from the face of an original  See Counter proof under Counter'),
(22101, 'Counter roll', 'A duplicate roll record or account kept by an officer as a check upon another officers roll'),
(22102, 'Counterrolment', 'A counter account See Control'),
(22103, 'counter sabotage', 'counterintelligence designed to detect and counteract sabotage'),
(22104, 'Counter salient', 'Leaping from each other    said of two figures on a coat of arms'),
(22105, 'Counterscale', 'Counterbalance balance as of one scale against another'),
(22106, 'Counterscarf', 'See counterscarp'),
