(22185, 'Courb', 'Curved rounded'),
(22186, 'Courbaril', 'See Anim'),
(22187, 'Courche', 'A square piece of linen used formerly by women instead of a cap a kerchief'),
(22188, 'courgette', 'a marrow squash plant whose fruit are eaten when small    called also zucchini'),
(22189, 'Courier', 'A messenger sent with haste to convey letters or dispatches usually on public business'),
(22190, 'Courlan', 'A South American bird of the genus Aramus allied to the rails'),
(22191, 'Course', 'The act of moving from one point to another progress passage'),
(22192, 'Coursed', 'Hunted as a coursed hare'),
