(31246, 'Electrizer', 'One who or that which electrizes'),
(31247, 'Electro ', 'A prefix or combining form signifying pertaining to electricity produced by electricity producing or employing electricity etc as electro negative electro dynamic electro magnet'),
(31248, 'Electro ballistic', 'Pertaining to electro ballistics'),
(31249, 'Electro ballistics', 'The art or science of measuring the force or velocity of projectiles by means of electricity'),
