INSERT INTO `dictionary` (`id`, `word`, `definition`) VALUES
(37555, 'Flybane', 'A kind of catchfly of the genus Silene also a poisonous mushroom Agaricus muscarius fly agaric'),
(37556, 'Fly bitten', 'Marked by or as if by the bite of flies'),
(37557, 'Flyblow', 'To deposit eggs upon as a flesh fly does on meat to cause to be maggoty hence to taint or contaminate as if with flyblows'),
