INSERT INTO `dictionary` (`id`, `word`, `definition`) VALUES
(45640, 'Hornbeam', 'A tree of the genus Carpinus Carpinus Americana having a smooth gray bark and a ridged trunk the wood being white and very hard  It is common along the banks of streams in the United States and is also called ironwood  The English hornbeam is Carpinus Betulus  The American is called also blue beech and water beech'),
(45641, 'Hornbill', 'Any bird of the family Bucerotid'),
(45642, 'Hornblende', 'The common black or dark green or brown variety of amphibole See Amphibole It belongs to the aluminous division of the species and is also characterized by its containing considerable iron Also used as a general term to include the whole species'),
(45643, 'Hornblendic', 'Composed largely of hornblende resembling or relating to hornblende'),
(45644, 'Hornblower', 'One who or that which blows a horn'),
(45645, 'Hornbook', 'The first book for children or that from which in former times they learned their letters and rudiments    so called because a sheet of horn covered the small thin board of oak or the slip of paper on which the alphabet digits and often the Lords Prayer were written or printed a primer'),
(45646, 'Hornbug', 'A large nocturnal beetle of the genus Lucanus as Lucanus capreolus and Lucanus dama having long curved upper jaws resembling a sickle  The grubs are found in the trunks of old trees'),
(45647, 'Horned', 'Furnished with a horn or horns furnished with a hornlike process or appendage as horned cattle having some part shaped like a horn'),
