(51822, 'JD', 'juvenile delinquent'),
(51823, 'JDL', 'Jewish Defense League'),
(51824, 'Jealoushood', 'Jealousy'),
(51825, 'Jealously', 'In a jealous manner'),
(51826, 'Jealousness', 'State or quality of being jealous'),
