(51861, 'Jemidar', 'The chief or leader of a band or body of persons esp in the native army of India an officer of a rank corresponding to that of lieutenant in the English army'),
(51862, 'Jemlah goat', 'The jharal'),
(51863, 'Jemminess', 'Spruceness'),
