(51865, 'Jeniquen', 'A Mexican name for the Sisal hemp Agave rigida var Sisalana also its fiber'),
(51866, 'Jenite', 'See Yenite'),
(51867, 'Jenkins', 'A name of contempt for a flatterer of persons high in social or official life as the Jenkins employed by a newspaper'),
(51868, 'Jennet', 'A small Spanish horse a genet'),
(51869, 'Jenneting', 'A variety of early apple See Juneating'),
(51870, 'Jenny', 'A machine for spinning a number of threads at once    used in factories  Also called spinning jenny'),
(51871, 'Jentling', 'A fish of the genus Leuciscus the blue chub of the Danube'),
(51872, 'Jeofail', 'An oversight in pleading or the acknowledgment of a mistake or oversight'),
