(51896, 'Jerquer', 'A customhouse officer who searches ships for unentered goods'),
(51897, 'Jerquing', 'The searching of a ship for unentered goods'),
(51898, 'Jerry', 'Flimsy jerry built'),
(51899, 'Jerry builder', 'A professional builder who erects cheap dwellings of poor materials and unsubstantial and slovenly construction'),
(51900, 'Jerry built', 'Built hastily and of bad materials as jerry built houses'),
