(56286, 'losings', 'something lost especially money lost at gambling  Inverse of winnings'),
(56287, 'Loss', 'The act of losing failure destruction privation as the loss of property loss of money by gaming loss of health or reputation'),
(56288, 'losses', 'something lost especially money lost at gambling  Inverse of winnings'),
(56289, 'Lossful', 'Detrimental'),
