(56405, 'lower middle class', 'occupying the lower part of the middle socioeconomic range in a society'),
(56406, 'Lowermost', 'Lowest'),
(56407, 'lower ranking', 'inferior in rank or status'),
(56408, 'Lowery', 'Cloudy gloomy lowering as a lowery sky lowery weather'),
(56409, 'Lowgh', 'strong imp of Laugh'),
(56410, 'low grade', 'inferior as low grade ore  Opposite of high grade'),
