INSERT INTO `dictionary` (`id`, `word`, `definition`) VALUES
(56910, 'Macavahu', 'A small Brazilian monkey Callithrix torquatus    called also collared teetee'),
(56911, 'Macaw', 'Any parrot of the genus Ara Sittace or Macrocercus  About eighteen species are known all of them found in Central and South America  They are large and have a very long tail a strong hooked bill and a naked space around the eyes  The voice is harsh and the colors are brilliant and strongly contrasted they are among the largest and showiest of parrots  Different species names have been given to the same macaw as for example the Hyacinthine macaw which has been variously classified as Anodorhyncus hyacynthinus Anodorhyncus maximiliani and Macrocercus hyacynthinus'),
(56912, 'Maccabean', 'Of or pertaining to Judas Maccabeus or to the Maccabees as the Maccabean princes Maccabean times'),
(56913, 'Maccabees', 'The name given in later times to the Asmonaeans a family of Jewish patriots who headed a religious revolt in the reign of Antiochus IV 168 161 b c which led to a period of freedom for Israel'),
(56914, 'Maccaboy', 'A kind of snuff'),
