(59344, 'mem', 'the 13th letter of the Hebrew alphabet'),
(59345, 'Member', 'To remember to cause to remember to mention'),
(59346, 'Membered', 'Having limbs    chiefly used in composition'),
(59347, 'Membership', 'The state of being a member'),
(59348, 'Membral', 'Relating to a member'),
(59349, 'Membrane', 'A thin layer or fold of tissue usually supported by a fibrous network serving to cover or line some part or organ and often secreting or absorbing certain fluids'),
(59350, 'Membraneous', 'See Membranous'),
(59351, 'Membraniferous', 'Having or producing membranes'),
