(64516, 'Noemics', 'The science of the understanding intellectual science'),
(64517, 'Noetian', 'One of the followers of Noetus who lived in the third century  He denied the distinct personality of the Father Son and Holy Ghost'),
(64518, 'Noetic', 'Of or pertaining to the intellect intellectual'),
(64519, 'Nof', 'Not of nor of'),
(64520, 'Nog', 'A noggin'),
