(64585, 'Nominatival', 'Of or pertaining to the nominative case'),
(64586, 'Nominative', 'Giving a name naming designating    said of that case or form of a noun which stands as the subject of a finite verb'),
(64587, 'Nominatively', 'In the manner of a nominative as a nominative'),
(64588, 'Nominator', 'One who nominates'),
