(64595, 'Nomothetic', 'Legislative enacting laws as a nomothetical power'),
(64596, 'Non', 'No not See No a'),
(64597, 'Nona', 'The Fate who spins the thread of life counterpart of Greek Clotho'),
(64598, 'Nonability', 'Want of ability'),
