(64600, 'Nonacceptance', 'A neglect or refusal to accept'),
(64601, 'Nonacid', 'Destitute of acid properties hence basic metallic positive    said of certain atoms and radicals'),
(64602, 'Nonacquaintance', 'Want of acquaintance the state of being unacquainted'),
(64603, 'Nonacquiescence', 'Refusal of acquiescence failure to yield or comply'),
(64604, 'Nonadmission', 'Failure to be admitted'),
(64605, 'nonadsorbent', 'lacking capacity to adsorb or cause to accumulate on a surface  Opposite of adsorbent'),
(64606, 'Nonadult', 'Not adult immature'),
(64607, 'Nonaerobiotic', 'Capable of living without atmospheric oxygen anaerobic'),
