(64609, 'Nonaged', 'Having the quality of nonage being a minor immature'),
(64610, 'Nonagenarian', 'A person ninety years old'),
(64611, 'Nonagesimal', 'Of or pertaining to the ninetieth degree or to a nonagesimal'),
(64612, 'Nonagon', 'A plane figure or polygon having nine sides and nine angles'),
(64613, 'Nonagrian', 'Any moth of the genus Nonagria and allied genera as the spindleworm and stalk borer'),
(64614, 'Nonalienation', 'Failure to alienate also the state of not being alienated'),
(64615, 'Nonane', 'One of a group of metameric hydrocarbons C9H20 of the paraffin series    so called because of the nine carbon atoms in the molecule Normal nonane is a colorless volatile liquid an ingredient of ordinary kerosene'),
(64616, 'Nonappearance', 'Default of appearance as in court to prosecute or defend failure to appear'),
(64617, 'Nonappointment', 'Neglect of making appointment failure to receive an appointment'),
(64618, 'nonarboreal', 'not arboreal not living in trees    of animals  Opposite of arboreal'),
(64619, 'Nonarrival', 'Failure to arrive'),
(64620, 'nonassociative', 'not associative  Opposite of associative'),
(64621, 'Non assumpsit', 'The general plea or denial in an action of assumpsit'),
(64622, 'nonastringent', 'noncontractive  Opposite of astringent'),
(64623, 'Nonattendance', 'A failure to attend omission of attendance nonappearance'),
