(64626, 'nonbearing', 'supporting no vertical weight other than its own    of a structural member as a non bearing wall'),
(64627, 'nonbelligerent', 'not directly at war as nonbelligerent nations'),
(64628, 'Nonbituminous', 'Containing no bitumen not bituminous'),
(64629, 'noncarbonated', 'not having supersaturated carbon dioxide in solution not carbonated    of beverages'),
