(64631, 'noncausal', 'not causal'),
(64632, 'noncausative', 'not causative  Opposite of causative'),
(64633, 'Nonce', 'The one or single occasion the present call or purpose    chiefly used in the phrase for the nonce i e for the present time'),
(64634, 'noncellular', 'Not made up of or divided into cells  Opposite of cellular'),
(64635, 'Nonchalance', 'Indifference carelessness coolness'),
