(64638, 'Nonclaim', 'A failure to make claim within the time limited by law omission of claim'),
(64639, 'Noncohesion', 'Want of cohesion'),
(64640, 'Noncoincidence', 'Lack of coincidence'),
(64641, 'Noncoincident', 'Not coincident'),
(64642, 'noncollapsable', 'not able to be folded into a compact form  Opposite of collapsible'),
(64643, 'noncolumned', 'not having columns'),
(64644, 'noncom', 'A noncommissioned officer a military officer appointed from enlisted personnel'),
(64645, 'Noncombatant', 'Any person connected with an army or within the lines of an army who does not make it his business to fight as any one of the medical officers and their assistants chaplains and others also any of the citizens of a place occupied by an army also any one holding a similar position with respect to the navy'),
(64646, 'noncombinative', 'not combinative  Opposite of combinative'),
