(72052, 'Phlegmagogue', 'A medicine supposed to expel phlegm'),
(72053, 'Phlegmasia', 'An inflammation more particularly an inflammation of the internal organs'),
(72054, 'Phlegmatic', 'Watery'),
(72055, 'Phlegmatical', 'Phlegmatic'),
(72056, 'Phlegmatically', 'In a phlegmatic manner'),
