(72124, 'Phonograph', 'A character or symbol used to represent a sound esp one used in phonography'),
(72125, 'Phonographer', 'One versed or skilled in phonography'),
(72126, 'Phonographic', 'Of or pertaining to phonography based upon phonography'),
(72127, 'Phonographically', 'In a phonographic manner by means of phonograph'),
(72128, 'Phonographist', 'Phonographer'),
(72129, 'Phonography', 'A description of the laws of the human voice or sounds uttered by the organs of speech'),
(72130, 'Phonolite', 'A compact feldspathic igneous rock containing nephelite ha'),
