(72141, 'Phonotypist', 'One versed in phonotypy'),
(72142, 'Phonotypy', 'A method of phonetic printing of the English language as devised by Mr Pitman in which nearly all the ordinary letters and many new forms are employed in order to indicate each elementary sound by a separate character'),
(72143, 'phony', 'imitating something superior intended to deceive fraudulent having a misleading appearance not genuine counterfeit fake as a phony diamond a phony hundred dollar bill'),
(72144, ' phore', 'Combining form meaning bearer of the element preceding as ionophore semaphore'),
(72145, 'Phorminx', 'A kind of lyre used by the Greeks'),
(72146, 'Phormium', 'A genus of liliaceous plants consisting of one species Phormium tenax See Flax plant'),
(72147, 'Phorone', 'A yellow crystalline substance having a geraniumlike odor regarded as a complex derivative of acetone and obtained from certain camphor compounds'),
