(72302, 'Phraseology', 'Manner of expression peculiarity of diction style'),
(72303, 'Phrasing', 'Method of expression association of words'),
(72304, 'Phratry', 'A subdivision of a phyle or tribe in Athens'),
(72305, 'Phreatic', 'Subterranean    applied to sources supplying wells'),
(72306, 'Phrenetic', 'Relating to phrenitis suffering from frenzy delirious mad frantic frenetic'),
(72307, 'phren ', 'A combining form meaning of or pertaining to the diaphragm the mind or the brain frenic'),
(72308, 'Phrenic', 'Of or pertaining to the diaphragm diaphragmatic as the phrenic nerve'),
(72309, 'Phrenics', 'That branch of science which relates to the mind mental philosophy'),
(72310, 'Phrenism', 'See Vital force under Vital'),
(72311, 'Phrenitis', 'Inflammation of the brain or of the meninges of the brain attended with acute fever and delirium    called also cephalitis'),
