(72313, 'Phrenologer', 'A phrenologist'),
(72314, 'Phrenologic', 'Phrenological'),
(72315, 'Phrenological', 'Of or pertaining to phrenology'),
(72316, 'Phrenologist', 'One versed in phrenology a craniologist'),
