(73163, 'Place proud', 'Proud of rank or office'),
(73164, 'Placer', 'One who places or sets'),
(73165, 'Placet', 'A vote of assent as of the governing body of a university of an ecclesiastical council etc'),
(73166, 'Placid', 'Pleased contented unruffied undisturbed serene peaceful tranquil quiet gentle'),
(73167, 'Placidity', 'The quality or state of being placid calmness serenity'),
(73168, 'Placidly', 'In a placid manner'),
(73169, 'Placidness', 'The quality or state of being placid'),
(73170, 'Placit', 'A decree or determination a dictum'),
(73171, 'Placitory', 'Of or pertaining to pleas or pleading in courts of law'),
(73172, 'Placitum', 'A public court or assembly in the Middle Ages over which the sovereign president when a consultation was held upon affairs of state'),
(73173, 'Plack', 'A small copper coin formerly current in Scotland worth less than a cent'),
(73174, 'Placket', 'A petticoat esp an under petticoat hence a cant term for a woman'),
