(73186, 'Plagal', 'Having a scale running from the dominant to its octave    said of certain old church modes or tunes as opposed to those called authentic which ran from the tonic to its octave'),
(73187, 'Plagate', 'Having plag'),
(73188, 'Plage', 'A region country'),
(73189, 'plagiarise', 'Same as plagiarize'),
(73190, 'Plagiarism', 'The act or practice of plagiarizing'),
