INSERT INTO `dictionary` (`id`, `word`, `definition`) VALUES
(74753, 'Post impressionism', 'In the broadest sense the theory or practice of any of several groups of painters of the early 1900s or of these groups taken collectively whose work and theories have in common a tendency to reaction against the scientific and naturalistic character of impressionism and neo impressionism In a strict sense the term post impressionism is used to denote the effort at self expression rather than representation shown in the work of C'),
(74754, 'Posting', 'The act of traveling post'),
(74755, 'Post it note', 'A small sheet of paper having the back part partly covered with a non permanent gum which allows the note to be attached temporarily to another object and easily removed without leaving any trace of glue on the object to which it was affixed  Such note papers are sold in pads of varying sizes'),
(74756, 'Postliminiar', 'Contrived done or existing subsequently'),
(74757, 'Postliminiary', 'Pertaining to or involving the right of postliminium'),
