(76826, 'Psalmody', 'The act practice or art of singing psalms or sacred songs also psalms collectively or a collection of psalms'),
(76827, 'Psalmograph', 'A writer of psalms a psalmographer'),
(76828, 'Psalmographer', 'A writer of psalms or sacred songs and hymns'),
(76829, 'Psalmography', 'The act or practice of writing psalms or sacred songs'),
(76830, 'Psalter', 'The Book of Psalms    often applied to a book containing the Psalms separately printed'),
