(77000, 'Ptyalogogue', 'A ptysmagogue'),
(77001, 'Ptysmagogue', 'A medicine that promotes the discharge of saliva'),
(77002, 'Ptyxis', 'The way in which a leaf is sometimes folded in the bud'),
(77003, 'pub', 'A retail business where alcoholic beverages are sold by the drink a bar a tavern'),
(77004, 'Pubble', 'Puffed out pursy pudgy fat'),
(77005, 'pub crawl', 'to go from one pub or tavern to the next and get progressively more drunk'),
(77006, 'Puberal', 'Of or pertaining to puberty'),
(77007, 'Puberty', 'The earliest age at which persons are capable of begetting or bearing children usually considered in temperate climates to be about fourteen years in males and twelve in females'),
(77008, 'Puberulent', 'Very minutely downy'),
