INSERT INTO `dictionary` (`id`, `word`, `definition`) VALUES
(79686, 'Reflex', 'Directed back attended by reflection retroactive introspective'),
(79687, 'Reflexed', 'Bent backward or outward'),
(79688, 'Reflexibility', 'The quality or capability of being reflexible as the reflexibility of the rays of light'),
