(83687, 'Scala', 'A machine formerly employed for reducing dislocations of the humerus'),
(83688, 'Scalable', 'Capable of being scaled'),
(83689, 'Scalade', 'See Escalade'),
(83690, 'Scalar', 'In the quaternion analysis a quantity that has magnitude but not direction    distinguished from a vector which has both magnitude and direction'),
