(86419, 'Shiel', 'A sheeling'),
(86420, 'Shield', 'A broad piece of defensive armor carried on the arm    formerly in general use in war for the protection of the body See Buckler'),
(86421, 'Shield bearer', 'One who or that which carries a shield'),
(86422, 'Shielddrake', 'A sheldrake'),
(86423, 'Shieldless', 'Destitute of a shield or of protection'),
(86424, 'Shieldtail', 'Any species of small burrowing snakes of the family Uropeltidae native of Ceylon and Southern Asia They have a small mouth which can not be dilated'),
(86425, 'Shieling', 'A hut or shelter for shepherds of fishers See Sheeling'),
(86426, 'Shift', 'To divide to distribute to apportion'),
(86427, 'Shiftable', 'Admitting of being shifted'),
(86428, 'Shifter', 'One who or that which shifts one who plays tricks or practices artifice a cozener'),
(86429, 'Shiftiness', 'The quality or state of being shifty'),
(86430, 'Shifting', 'Changing in place position or direction varying variable fickle as shifting winds shifting opinions or principles'),
(86431, 'Shiftingly', 'In a shifting manner'),
(86432, 'Shiftless', 'Destitute of expedients or not using successful expedients characterized by failure especially by failure to provide for ones own support through negligence or incapacity hence lazy improvident thriftless as a shiftless fellow shiftless management'),
