(86472, 'Shipboard', 'A ships side hence by extension a ship    found chiefly in adverbial phrases as on shipboard a shipboard'),
(86473, 'Shipbuilder', 'A person whose occupation is to construct ships and other vessels a naval architect a shipwright'),
(86474, 'Shipbuilding', 'Naval architecturel the art of constructing ships and other vessels'),
(86475, 'Shipful', 'As much or as many as a ship will hold enough to fill a ship'),
(86476, 'Shipholder', 'A shipowner'),
(86477, 'Shipless', 'Destitute of ships'),
(86478, 'Shiplet', 'A little ship'),
