(86480, 'Shipman', 'A seaman or sailor'),
(86481, 'Shipmaster', 'The captain master or commander of a ship'),
(86482, 'Shipmate', 'One who serves on board of the same ship with another a fellow sailor'),
(86483, 'Shipment', 'The act or process of shipping as he was engaged in the shipment of coal for London an active shipment of wheat from the West'),
(86484, 'Shipowner', 'Owner of a ship or ships'),
(86485, 'Shippen', 'A stable a cowhouse'),
(86486, 'Shipper', 'One who sends goods from one place to another not in the same city or town esp one who sends goods by water'),
(86487, 'Shipping', 'Relating to ships their ownership transfer or employment as shiping concerns'),
(86488, 'Shipping note', 'A document used in shipping goods by sea In the case of free goods the shipping notes are the receiving note addressed by the shipper to the chief officer of the vessel requesting him to receive on board specified goods and a receipt for the mate to sign on receiving whose signature it is called the mates receipt and is surrendered by the shipper for the bills of lading'),
(86489, 'Shippo', 'Cloisonn'),
(86490, 'Shippon', 'A cowhouse a shippen'),
