(86572, 'Shooty', 'Sprouting or coming up freely and regularly'),
(86573, 'Shop', 'imp of Shape Shaped'),
(86574, 'Shopboard', 'A bench or board on which work is performed a workbench'),
(86575, 'Shopbook', 'A book in which a tradesman keeps his accounts'),
(86576, 'Shopboy', 'A boy employed in a shop'),
(86577, 'Shopen', 'p p of Shape'),
(86578, 'Shopgirl', 'A girl employed in a shop'),
(86579, 'Shopkeeper', 'A trader who sells goods in a shop or by retail    in distinction from one who sells by wholesale'),
(86580, 'Shoplifter', 'One who steals anything in a shop or takes goods privately from a shop one who under pretense of buying goods takes occasion to steal'),
(86581, 'Shoplifting', 'Larceny committed in a shop the stealing of anything from a shop'),
(86582, 'Shoplike', 'Suiting a shop vulgar'),
(86583, 'Shopmaid', 'A shopgirl'),
(86584, 'Shopman', 'A shopkeeper a retailer'),
(86585, 'Shopper', 'One who shops'),
(86586, 'Shoppish', 'Having the appearance or qualities of a shopkeeper or shopman'),
(86587, 'Shoppy', 'Abounding with shops'),
