(88186, 'Snipefish', 'The bellows fish'),
(88187, 'Snippack', 'The common snipe'),
(88188, 'Snipper', 'One who snips'),
(88189, 'Snipper snaper', 'A small insignificant fellow'),
(88190, 'Snippet', 'A small part or piece'),
(88191, 'Snippety', 'Ridiculously small petty'),
(88192, 'Snip snap', 'A tart dialogue with quick replies'),
