INSERT INTO `dictionary` (`id`, `word`, `definition`) VALUES
(90312, 'Starboard', 'That side of a vessel which is on the right hand of a person who stands on board facing the bow    opposed to larboard or port'),
(90313, 'Star bowlines', 'The men in the starboard watch'),
(90314, 'Starch', 'Stiff precise rigid'),
(90315, 'Star chamber', 'An ancient high court exercising jurisdiction in certain cases mainly criminal which sat without the intervention of a jury  It consisted of the kings council or of the privy council only with the addition of certain judges  It could proceed on mere rumor or examine witnesses it could apply torture  It was abolished by the Long Parliament in 1641'),
