(90425, 'Stative', 'Of or pertaining to a fixed camp or military posts or quarters'),
(90426, 'Statoblast', 'One of a peculiar kind of internal buds or germs produced in the interior of certain Bryozoa and sponges especially in the fresh water species    also called winter buds'),
(90427, 'Statocracy', 'Government by the state or by political power in distinction from government by ecclesiastical power'),
(90428, 'stator', 'A stationary part in or about which another part the rotor revolves esp when both are large'),
(90429, 'stats', 'Shortened form of statistics2 b'),
(90430, 'Statua', 'A statue'),
(90431, 'Statuary', 'One who practices the art of making statues'),
(90432, 'Statue', 'The likeness of a living being sculptured or modeled in some solid substance as marble bronze or wax an image as a statue of Hercules or of a lion'),
