INSERT INTO `dictionary` (`id`, `word`, `definition`) VALUES
(90839, 'Stilbite', 'A common mineral of the zeolite family a hydrous silicate of alumina and lime usually occurring in sheaflike aggregations of crystals also in radiated masses It is of a white or yellowish color with pearly luster on the cleavage surface Called also desmine'),
(90840, 'Stile', 'A pin set on the face of a dial to cast a shadow a style See Style'),
(90841, 'Stilet', 'A stiletto'),
(90842, 'Stiletto', 'A kind of dagger with a slender rounded and pointed blade'),
(90843, 'Still', 'Motionless at rest quiet as to stand still to lie or sit still'),
(90844, 'Stillage', 'A low stool to keep the goods from touching the floor'),
(90845, 'Stillatitious', 'Falling in drops drawn by a still'),
(90846, 'Stillatory', 'An alembic a vessel for distillation'),
(90847, 'Stillbirth', 'The birth of a dead fetus'),
