(90852, 'Stillhouse', 'A house in which distillation is carried on a distillery'),
(90853, 'Still hunt', 'A hunting for game in a quiet and cautious manner or under cover stalking hence colloquially the pursuit of any object quietly and cautiously'),
(90854, 'Stillicide', 'A continual falling or succession of drops rain water falling from the eaves'),
(90855, 'Stillicidious', 'Falling in drops'),
(90856, 'Stilliform', 'Having the form of a drop'),
(90857, 'Stilling', 'A stillion'),
(90858, 'Stillion', 'A stand as for casks or vats in a brewery or for pottery while drying'),
(90859, 'Still life', 'a type of painting in which inanimate objects such as flowers or fruit are represented'),
(90860, 'Stillness', 'The quality or state of being still quietness silence calmness inactivity'),
