(92288, 'Sudatory', 'Sweating perspiring'),
(92289, 'Sudd', 'A tangled mass of floating vegetal matter obstructing navigation'),
(92290, 'Sudden', 'Happening without previous notice or with very brief notice coming unexpectedly or without the common preparation immediate instant speedy'),
(92291, 'Suddenty', 'Suddenness a sudden'),
(92292, 'Sudoral', 'Of or pertaining to sweat as sudoral eruptions'),
