(93533, 'Symmetrist', 'One eminently studious of symmetry of parts'),
(93534, 'Symmetrize', 'To make proportional in its parts to reduce to symmetry'),
(93535, 'Symmetry', 'A due proportion of the several parts of a body to each other adaptation of the form or dimensions of the several parts of a thing to each other the union and conformity of the members of a work to the whole'),
(93536, 'Sympathetic', 'Inclined to sympathy sympathizing'),
