(94549, 'Teem', 'To pour    commonly followed by out as to teem out ale'),
(94550, 'Teemer', 'One who teems or brings forth'),
(94551, 'Teemful', 'Pregnant prolific'),
(94552, 'Teeming', 'Prolific productive'),
(94553, 'Teemless', 'Not fruitful or prolific barren as a teemless earth'),
(94554, 'Teen', 'Grief sorrow affiction pain'),
(94555, 'Teenage', 'The longer wood for making or mending fences'),
