(94698, 'Tellina', 'A genus of marine bivalve mollusks having thin delicate and often handsomely colored shells'),
(94699, 'Telling', 'Operating with great effect effective as a telling speech'),
(94700, 'Telltale', 'Telling tales babbling'),
(94701, 'Tellural', 'Of or pertaining to the earth'),
(94702, 'Tellurate', 'A salt of telluric acid'),
(94703, 'Telluret', 'A telluride'),
(94704, 'Tellureted', 'Combined or impregnated with tellurium tellurized'),
(94705, 'Tellurhydric', 'Of pertaining to or designating hydrogen telluride which is regarded as an acid especially when in solution'),
(94706, 'Tellurian', 'Of or pertaining to the earth'),
(94707, 'Telluric', 'Of or pertaining to the earth proceeding from the earth'),
(94708, 'Telluride', 'A compound of tellurium with a more positive element or radical    formerly called telluret'),
