(94729, 'Temper', 'To mingle in due proportion to prepare by combining to modify as by adding some new element to qualify as by an ingredient hence to soften to mollify to assuage to soothe to calm'),
(94730, 'Tempera', 'A mode or process of painting distemper'),
(94731, 'Temperable', 'Capable of being tempered'),
(94732, 'Temperament', 'Internal constitution state with respect to the relative proportion of different qualities or constituent parts'),
(94733, 'Temperamental', 'Of or pertaining to temperament constitutional'),
(94734, 'Temperance', 'Habitual moderation in regard to the indulgence of the natural appetites and passions restrained or moderate indulgence moderation as temperance in eating and drinking temperance in the indulgence of joy or mirth specifically moderation and sometimes abstinence in respect to using intoxicating liquors'),
(94735, 'Temperancy', 'Temperance'),
(94736, 'Temperate', 'Moderate not excessive as temperate heat a temperate climate'),
