(95573, 'Thermocouple', 'A thermoelectric couple'),
(95574, 'Thermocurrent', 'A current developed or set in motion by heat specif an electric current in a heterogeneous circuit due to differences of temperature between the junctions of the substances of which the circuit is composed'),
(95575, 'Thermodin', 'A white crystalline substance derived from urethane used in medicine as an antipyretic etc'),
(95576, 'Thermodynamic', 'Relating to thermodynamics caused or operated by force due to the application of heat'),
(95577, 'Thermodynamics', 'The science which treats of the mechanical action or relations of heat'),
(95578, 'Thermoelectric', 'Pertaining to thermoelectricity as thermoelectric currents'),
(95579, 'Thermoelectric couple', 'A union of two conductors as bars or wires of dissimilar metals joined at their extremities for producing a thermoelectric current'),
(95580, 'Thermoelectricity', 'Electricity developed in the action of heat See the Note under Electricity'),
