(95582, 'Thermogen', 'Caloric heat regarded as a material but imponderable substance'),
(95583, 'Thermogenic', 'Relating to heat or to the production of heat producing heat thermogenous as the thermogenic tissues'),
(95584, 'Thermogenous', 'Producing heat thermogenic'),
(95585, 'Thermogram', 'The trace or record made by means of a thermograph'),
