(95594, 'Thermolyze', 'To subject to thermolysis to dissociate by heat'),
(95595, 'Thermomagnetism', 'Magnetism as affected or caused by the action of heat the relation of heat to magnetism'),
(95596, 'Thermometer', 'An instrument for measuring temperature founded on the principle that changes of temperature in bodies are accompanied by proportional changes in their volumes or dimensions'),
(95597, 'Thermometric', 'Of or pertaining to a thermometer as the thermometrical scale or tube'),
(95598, 'Thermometrically', 'In a thermometrical manner by means of a thermometer'),
(95599, 'Thermometrograph', 'An instrument for recording graphically the variations of temperature or the indications of a thermometer'),
(95600, 'Thermometry', 'The estimation of temperature by the use of a thermometric apparatus'),
(95601, 'Thermomotor', 'A heat engine a hot air engine'),
(95602, 'Thermomultiplier', 'Same as Thermopile'),
(95603, 'Thermoneurosis', 'A neurosis caused by exposure to heat'),
(95604, 'Thermoneutrality', 'Neutrality as regards heat effects'),
(95605, 'Thermophilic', 'Heat loving    applied especially to microorganisms such as certain bacteria fungi and algae which grow best at temperatures above 40'),
