(97176, 'trades union', 'An organized combination among workmen for the purpose of maintaining their rights privileges and interests with respect to wages hours of labor customs etc'),
(97177, 'Trades unionist', 'A member of a trades union or a supporter of trades unions'),
(97178, 'Tradeswoman', 'A woman who trades or is skilled in trade'),
(97179, 'Trading', 'Carrying on trade or commerce engaged in trade as a trading company'),
(97180, 'Tradition', 'The act of delivering into the hands of another delivery'),
