(98975, 'Tyfoon', 'See Typhoon'),
(98976, 'Tyger', 'A tiger'),
(98977, 'Tying', 'p pr of Tie'),
(98978, 'Tyke', 'See 2d Tike'),
(98979, 'Tylarus', 'One of the pads on the under surface of the toes of birds'),
(98980, 'Tyler', 'See 2d Tiler'),
(98981, 'Tylopoda', 'A tribe of ungulates comprising the camels'),
(98982, 'Tylosis', 'An intrusion of one vegetable cell into the cavity of another sometimes forming there an irregular mass of cells'),
(98983, 'Tymbal', 'A kind of kettledrum'),
(98984, 'Tymp', 'A hollow water cooled iron casting in the upper part of the archway in which the dam stands'),
(98985, 'Tympan', 'A drum'),
(98986, 'Tympanal', 'Tympanic'),
(98987, 'Tympanic', 'Like a tympanum or drum acting like a drumhead as a tympanic membrane'),
