(105024, 'Vulgarness', 'The quality of being vulgar'),
(105025, 'Vulgate', 'An ancient Latin version of the Scripture and the only version which the Roman Church admits to be authentic    so called from its common use in the Latin Church'),
(105026, 'Vulnerability', 'The quality or state of being vulnerable vulnerableness'),
(105027, 'Vulnerableness', 'The quality or state of being vulnerable vulnerability'),
(105028, 'Vulnerary', 'Useful in healing wounds adapted to the cure of external injuries as vulnerary plants or potions'),
(105029, 'Vulnerate', 'To wound to hurt'),
