INSERT INTO `dictionary` (`id`, `word`, `definition`) VALUES
(105890, 'weeping tree broom', 'a small shrubby tree of New Zealand having weeping branches and racemes of white to violet flowers followed by woolly indehiscent 2 seeded pods'),
(105891, 'weeping widow', 'same as crumblecap'),
(105892, 'Weeping willow', 'a tree Salix babylonica of the willow family with slender leaves native to China whose branches grow very long and slender and hang down almost perpendicularly  It grows best where soil is moist as by the banks of streams and is widely cultivated as an ornamental tree'),
