(106557, 'Windhover', 'The kestrel    called also windbibber windcuffer windfanner'),
(106558, 'Windiness', 'The quality or state of being windy or tempestuous as the windiness of the weather or the season'),
(106559, 'Winding', 'A call by the boatswains whistle'),
(106560, 'Windingly', 'In a winding manner'),
(106561, 'Windjammer', 'A sailing vessel or one of its crew    orig so called contemptuously by sailors on steam vessels'),
(106562, 'Windlace', 'See Windlass'),
(106563, 'Windlass', 'A winding and circuitous way a roundabout course a shift'),
(106564, 'Windless', 'Having no wind calm'),
(106565, 'Windlestrae', 'A grass used for making ropes or for plaiting esp Agrostis Spica ventis'),
