(107387, 'Yang', 'The cry of the wild goose a honk'),
(107388, 'Yangtze', 'a major river of Asia which flows into the East China Sea'),
(107389, 'Yank', 'A jerk or twitch'),
(107390, 'Yankee', 'A nickname for a native or citizen of New England especially one descended from old New England stock by extension an inhabitant of the Northern States as distinguished from a Southerner also applied sometimes by foreigners to any inhabitant of the United States'),
(107391, 'Yankee Doodle', 'The name of a tune adopted popularly as one of the national airs of the United States'),
(107392, 'Yankeeism', 'A Yankee idiom word custom or the like'),
(107393, 'Yaourt', 'A fermented drink or milk beer made by the Turks'),
